{
  "flashcards": [
    {
      "front": "What is the primary goal of designing for partial failure in distributed systems?",
      "back": "To ensure the system remains available and functional despite the failure of individual components, nodes, or network segments, preventing cascading failures through patterns like circuit breakers, retries with exponential backoff, and bulkheading.",
      "requirement_ids": [
        "r2"
      ]
    },
    {
      "front": "How do you achieve multi-tenant isolation in a shared Kubernetes cluster?",
      "back": "Use Namespaces for logical separation, NetworkPolicies for traffic control, ResourceQuotas/LimitRanges for resource consumption, and PodSecurityPolicies or Admission Controllers to enforce security contexts and prevent privilege escalation.",
      "requirement_ids": [
        "r3",
        "r5"
      ]
    },
    {
      "front": "What is the 'CAP theorem' and why does it matter for infrastructure design?",
      "back": "It states that a distributed system can only provide two of three guarantees: Consistency, Availability, and Partition Tolerance. In infrastructure, you must explicitly choose how to handle network partitions based on whether your service prioritizes data accuracy or uptime.",
      "requirement_ids": [
        "r2"
      ]
    },
    {
      "front": "What is the purpose of an RFC (Request for Comments) in platform engineering?",
      "back": "To document proposed architectural changes, gather feedback from stakeholders, and build consensus before implementation. It serves as a historical record of design decisions and ensures alignment across engineering teams.",
      "requirement_ids": [
        "r4"
      ]
    },
    {
      "front": "How do you handle 'noisy neighbor' problems in a multi-tenant platform?",
      "back": "Implement strict resource requests and limits, use priority classes to schedule critical workloads, and leverage node affinity or taints/tolerations to isolate high-demand tenants on dedicated hardware pools.",
      "requirement_ids": [
        "r3",
        "r5"
      ]
    },
    {
      "front": "What is the difference between 'Infrastructure as Code' and 'Configuration as Code'?",
      "back": "Infrastructure as Code (IaC) provisions the underlying resources (VPCs, clusters, databases). Configuration as Code manages the settings and state of applications running on that infrastructure (e.g., Helm charts, ConfigMaps, environment variables).",
      "requirement_ids": [
        "r1"
      ]
    },
    {
      "front": "When writing a post-mortem, what is the most important section?",
      "back": "The 'Action Items' section. It must contain concrete, assigned, and prioritized tasks that directly address the root cause to prevent recurrence. The narrative should be blameless and focus on systemic improvements.",
      "requirement_ids": [
        "r4"
      ]
    },
    {
      "front": "What is a 'Circuit Breaker' pattern and when should you use it?",
      "back": "A pattern that stops requests to a failing service after a threshold is met, allowing it time to recover. Use it to prevent cascading failures in distributed systems when a downstream dependency is unresponsive.",
      "requirement_ids": [
        "r2"
      ]
    },
    {
      "front": "How do you manage Kubernetes upgrades in a production environment with zero downtime?",
      "back": "Use a blue-green or canary upgrade strategy for nodes, ensure PodDisruptionBudgets are configured to maintain availability, and perform rolling updates for workloads to ensure enough replicas are always running during the transition.",
      "requirement_ids": [
        "r3"
      ]
    },
    {
      "front": "Why is 'observability' critical for a Staff-level platform engineer?",
      "back": "It moves beyond simple monitoring (is it up?) to understanding the internal state of complex systems (why is it slow?). It allows you to debug distributed systems by correlating logs, metrics, and traces across service boundaries.",
      "requirement_ids": [
        "r1",
        "r2"
      ]
    }
  ]
}
